const sources = [
  {
    name: 'contoh-portal',
    scrape_url: 'https://contoh-portal-loker.com/lowongan',
    base_url: 'https://contoh-portal-loker.com'
  }
  // Tambahkan sumber lain:
  // { name: 'glints', scrape_url: 'https://glints.com/id/lowongan', base_url: 'https://glints.com' }
];

return sources.map(s => ({ json: s }));

// ============================================
// GABUNGKAN HASIL EXTRACT MENJADI ARRAY JOBS
// ============================================

const data = $input.first().json;
const sourceConfig = $('Daftar Sumber Scraping').first().json;
const baseUrl = sourceConfig.base_url || '';
const sourceName = sourceConfig.name || 'unknown';

const titles = data.titles || [];
const companies = data.companies || [];
const locations = data.locations || [];
const links = data.links || [];
const descriptions = data.descriptions || [];

const jobs = [];

for (let i = 0; i < titles.length; i++) {
  const title = (titles[i] || '').trim();
  const company = (companies[i] || '').trim();
  const link = (links[i] || '').trim();

  if (!title || !link) continue;

  // Pastikan URL absolut
  const sourceUrl = link.startsWith('http') ? link : baseUrl + link;

  jobs.push({
    title,
    company: company || 'Tidak diketahui',
    location: (locations[i] || '').trim() || null,
    source_url: sourceUrl,
    employment_type: null,
    salary_min: null,
    salary_max: null,
    description_raw: (descriptions[i] || '').trim() || null,
    source_name: sourceName,
  });
}

if (jobs.length === 0) {
  throw new Error(
    `Tidak ada lowongan ditemukan dari ${sourceName}. ` +
    `Periksa CSS selector di node "Extract Data dari HTML".`
  );
}

return jobs.map(j => ({ json: j }));

