// Parse AI response dan gabungkan dengan data loker asli

const items = $input.all();
const batchItems = $('Batch per 5 Item').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const aiResponse = items[i].json;
  const original = batchItems[i]?.json || {};
  let summary = '';
  let tags = [];

  try {
    const content = aiResponse.choices?.[0]?.message?.content || '';
    let parsed = null;

    // Coba parse JSON langsung
    try {
      parsed = JSON.parse(content);
    } catch (e) {
      // Extract JSON dari text
      const jsonMatch = content.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try { parsed = JSON.parse(jsonMatch[0]); } catch (e2) {}
      }
    }

    if (parsed) {
      summary = parsed.summary || '';
      tags = Array.isArray(parsed.tags) ? parsed.tags : [];
    } else {
      // Regex fallback
      const sm = content.match(/(?:summary|ringkasan)[:\s]*(.+?)(?=\n|tags|$)/is);
      if (sm) summary = sm[1].trim();
      const tm = content.match(/(?:tags|label)[:\s]*(.+?)$/is);
      if (tm) tags = tm[1].split(',').map(t => t.trim().replace(/[\[\]"']/g, '')).filter(Boolean);
    }
  } catch (e) {
    summary = '';
    tags = [];
  }

  results.push({
    json: {
      title: original.title,
      company: original.company,
      location: original.location,
      source_url: original.source_url,
      employment_type: original.employment_type,
      salary_min: original.salary_min,
      salary_max: original.salary_max,
      description_raw: original.description_raw,
      summary_ai: summary,
      tags: tags,
      source_name: original.source_name,
    }
  });
}

return results;

// Kumpulkan semua hasil menjadi payload untuk ingest API

const items = $input.all();
const sourceName = items[0]?.json?.source_name || 'unknown';

const payload = {
  source: sourceName,
  scraped_at: new Date().toISOString(),
  jobs: items.map(item => ({
    title: item.json.title,
    company: item.json.company,
    location: item.json.location,
    employment_type: item.json.employment_type,
    salary_min: item.json.salary_min,
    salary_max: item.json.salary_max,
    description_raw: item.json.description_raw,
    summary_ai: item.json.summary_ai,
    tags: item.json.tags,
    source_url: item.json.source_url,
  }))
};

return [{ json: payload }];

// Log hasil ingest
const response = $input.first().json;

return [{ json: {
  status: 'SUCCESS',
  source: response.source || 'unknown',
  inserted: response.stats?.inserted || 0,
  updated: response.stats?.updated || 0,
  skipped: response.stats?.skipped || 0,
  errors: response.stats?.errors?.length || 0,
  timestamp: new Date().toISOString(),
} }];
